def catalog(prompt='',full=False):
 text=normalized(prompt);families=[k for k,pattern in DOMAINS.items() if re.search(pattern,text)]
 names=set(ACTION_CONTRACTS) if full or not families else {'memory_save','preferences_save','app_action'}|set().union(*(FAMILY_TYPES[k] for k in families))
 prefixes={'mail':('email_',),'tasks':('automation_','mission_','enterprise_'),'media':('editing_','growth_','publication_','production_','media_','project_role_'),'project':('project_','agent_','room_','connection_'),'code':('',),'computer':('',)}
 selected_docs=APP_OPERATION_DOCS if full or not families else {k:v for k,v in APP_OPERATION_DOCS.items() if any(k.startswith(p) for family in families for p in prefixes[family]) or ('skill' in text or 'munkamod' in text) and k.startswith('skill_')}
 return dict(families=families or ['general'],all_action_types=sorted(ACTION_CONTRACTS),allowed_app_operations=sorted(APP_ACTIONS),actions={k:v for k,v in ACTION_CONTRACTS.items() if k in names},reads=READ_CONTRACT,operation_contracts=selected_docs)

def prompt_contract(prompt='',full=False):
 data=catalog(prompt,full)
 reads='Read forms: {"turn":"earlier turn ID in this same chat"}, '+', '.join('{"app":"'+k+'","project":"exact project ID"}' for k in READ_CONTRACT)+', {"project":"id"}, {"agent":"id"}, {"room":"id","project":"id"}, {"connection":"id"}, {"job":"id","project":"id"}, {"models":true}, {"connections":true}, {"overview":true}, {"files":true,"project":"id"}, {"path":"absolute authorized path","offset":0}, {"search":"public web query"}, {"url":"public https URL"}, {"catalog":true}. One read per planning slice. Use catalog:true to discover complete contracts if a needed form is absent; absence from this shortlist is not an unavailable capability.'+'\n'+__import__('skill_api').CONTRACT
 return reads+'\nApp read descriptions: '+json.dumps(data['reads'],ensure_ascii=False)+'\nAction types: '+', '.join(data['all_action_types'])+'\nAllowed app operations: '+', '.join(data['allowed_app_operations'])+'\n'+'\n'.join(data['actions'].values())+'\nApp operation argument contracts: '+json.dumps(data['operation_contracts'],ensure_ascii=False)

